"""RQ2: classification of the INVALID cases generated by the LLM and effect of the repair loop (main runs).

Reads the PostgreSQL dumps (paper/runs/<run>/db.sql.gz) loaded into a throwaway Postgres (container `p07-pg`,
one database per manifest row, named r_<model size>_<benchmark>) through `docker exec psql` (no Python driver).

    docker run -d --name p07-pg -e POSTGRES_PASSWORD=p07 -e POSTGRES_USER=p07 postgres:16
    # loading: see paper/README.md, section "LLM failure taxonomy"
    python paper/analysis/llm_failure_taxonomy.py

Only cases with source LLM or HYBRID (the LLM part of HYBRID; the RULE seeds are stored with source RULE).
Main class of each INVALID case, in priority order:
ENDPOINT > FIELD > STATUS > VARIABLE > DSL_SCHEMA > JSON > OTHER.
Output: results/llm_invalid_by_class.csv, results/llm_repair_summary.csv.
"""
import io
import json
import os
import re
import subprocess

import pandas as pd

from params import MANIFEST

HERE = os.path.dirname(os.path.abspath(__file__))
RESULTS = os.path.join(HERE, "..", "results")
CONTAINER = os.environ.get("P07_PG", "p07-pg")

CLASSES = [  # (class, regex on the Vietnamese validator messages of web/ai-service)
    ("ENDPOINT", r"không tồn tại trong đặc tả|method .* không có|operation .* không tồn tại"),
    ("FIELD", r"không khai báo request body|tham số .* không (được )?khai báo|query .* không (được )?khai báo|header .* không (được )?khai báo"
              r"|Trường .* không tồn tại trong schema|Thiếu tham số (đường dẫn|truy vấn)? ?bắt buộc"),
    ("STATUS", r"Mã trạng thái HTTP .* không được khai báo"),
    ("VARIABLE", r"Biến .* chưa được định nghĩa"),
    ("DSL_SCHEMA", r"có trường không được phép|thiếu trường bắt buộc|sai kiểu dữ liệu|không được hỗ trợ|không hợp lệ, chỉ chấp nhận|không thuộc danh sách cho phép|rỗng|ít nhất"),
    ("JSON", r"JSON|parse|cắt|truncat"),
]


def db_name(model, bench):
    return "r_" + model.split(":")[1] + "_" + bench.replace("-", "_")


def query(db, sql):
    out = subprocess.run(["docker", "exec", CONTAINER, "psql", "-U", "p07", "-d", db, "-c",
                          f"COPY ({sql}) TO STDOUT WITH CSV HEADER"],
                         capture_output=True, check=True, env=dict(os.environ, MSYS_NO_PATHCONV="1"))
    return pd.read_csv(io.StringIO(out.stdout.decode("utf-8")))


def classify(errors):
    msgs = errors if isinstance(errors, list) else [errors]
    msgs = [m if isinstance(m, str) else json.dumps(m, ensure_ascii=False) for m in msgs]
    labels = [c for c, pat in CLASSES if any(re.search(pat, m, re.I) for m in msgs)]
    return (labels[0] if labels else "OTHER"), labels


def main():
    with open(MANIFEST, encoding="utf-8") as f:
        runs = json.load(f)["runs"]
    cases, calls = [], []
    for r in runs:
        db = db_name(r["model"], r["benchmark"])
        # source = LLM (LLM experiment) or HYBRID (LLM part of HYBRID) -> used as the strategy
        c = query(db, "SELECT id, source AS strategy, status, repair_attempts, validation_errors::text AS ve "
                      "FROM test_cases WHERE source IN ('LLM','HYBRID')")
        c["model"], c["benchmark"] = r["model"], r["benchmark"]
        cases.append(c)
        k = query(db, "SELECT purpose, count(*) AS n FROM llm_call_logs GROUP BY purpose")
        k["model"], k["benchmark"] = r["model"], r["benchmark"]
        calls.append(k)
    cases = pd.concat(cases, ignore_index=True).drop_duplicates(["model", "benchmark", "id"])
    calls = pd.concat(calls, ignore_index=True)

    inv = cases[cases.status == "INVALID"].copy()
    parsed = inv["ve"].apply(lambda s: json.loads(s) if isinstance(s, str) else [])
    inv["primary"], inv["labels"] = zip(*parsed.map(classify)) if len(inv) else ([], [])
    by_class = (inv.groupby(["model", "strategy", "primary"]).size().rename("n").reset_index())
    by_class.to_csv(os.path.join(RESULTS, "llm_invalid_by_class.csv"), index=False)

    cases["valid_final"] = cases.status.isin(["VALID", "DUPLICATE", "APPROVED"])
    cases["valid_first"] = cases.valid_final & (cases.repair_attempts == 0)
    cases["repaired"] = cases.repair_attempts > 0
    cases["repair_ok"] = cases.repaired & cases.valid_final
    summ = cases.groupby(["model", "strategy"]).agg(
        generated=("id", "size"), valid_final=("valid_final", "sum"), valid_first=("valid_first", "sum"),
        invalid=("status", lambda s: (s == "INVALID").sum()), went_to_repair=("repaired", "sum"),
        repair_ok=("repair_ok", "sum")).reset_index()
    rep_calls = calls[calls.purpose == "REPAIR"].groupby("model")["n"].sum()
    summ["repair_success_rate"] = summ.repair_ok / summ.went_to_repair.where(summ.went_to_repair > 0)
    summ.to_csv(os.path.join(RESULTS, "llm_repair_summary.csv"), index=False)
    pd.set_option("display.width", 200)
    print(summ.to_string(index=False))
    print(by_class.pivot_table(index="primary", columns=["model", "strategy"], values="n", fill_value=0).to_string())
    print("REPAIR calls per model:", rep_calls.to_dict())


if __name__ == "__main__":
    main()
